def numeric_compare(a, b):
    # Fixtures use numeric upstream versions; production apt_pkg is never invoked.
    def key(value):
        return tuple(map(int, re.match(r'^(\d+)\.(\d+)\.(\d+)', value).groups()))
    return (key(a) > key(b)) - (key(a) < key(b))


